/**
 * The abilities an object has, enumerated with STABLE KEYS (design 9.2, 15.2 WP9). Owner: WP9 (an addition to the files of design 5.1; rules/abilities.ts
 * re-exports from here, because `rules/characteristics` imports the layers and `statics` may not import `rules/abilities` back).
 *
 *   p:<face>:<index>         printed: FaceDef.abilities[index] of that face
 *   k:<face>:<index>:<n>     generated by the keyword library from the printed keyword ability at that index (n-th element of its expansion, design 7.1)
 *   g:<effectId>:<n>         granted by a continuous effect (layer 6 `add`, n-th element); the expansion of a granted keyword appends `:<j>`
 *   r:basic:<W|U|B|R|G>      rule-generated "{T}: Add {X}" of a basic land type (CR 305.6)
 *   r:saga, r:readAhead      M6-6: the intrinsic abilities of a Saga (CR 714.3a-b; statics/levels.ts)
 *   x:<face>:<index>:<n>     M6-6: what the printed Class level, leveler bracket or Case at that index stands for (CR 716.2a, 711.2a-b, 719.3a-c;
 *                            statics/levels.ts#layoutExpansion; `n` is a number or `solve`); a copied one is `c:<effectId>:<face>:<index>:x:<n>`
 *
 * Keys are stable across states, so a UI or bot can refer to an ability by (object id, key). A key never depends on the position of an ability among the
 * OTHER abilities of the object, only on where the ability comes from, so removing or granting one does not renumber the rest.
 */
import type { AbilityDef, ActivatedAbilityDef, KeywordAbilityDef } from '../types/ability';
import type { Color } from '../types/mana';
import { MANA_COST_OF_FACE_CAST } from '../keywords/expand';
import { keywordRegistry } from '../keywords/registry';
import type { ExpandContext } from '../keywords/types';
import type { BaseChars, Chars } from '../rules/characteristics';
import type { CharAbility } from './api';
import { layoutExpansion, sagaRuleAbilities } from './levels';
import { BASIC_LAND_TYPES } from './subtypes';

export const printedKey = (face: number, index: number): string => `p:${face}:${index}`;
export const keywordKey = (face: number, index: number, n: number): string => `k:${face}:${index}:${n}`;
export const grantedKey = (effectId: string, n: number): string => `g:${effectId}:${n}`;
export const basicKey = (color: Color): string => `r:basic:${color}`;
/** M6-6: the key of the `n`-th ability the printed layout structure at (face, index) stands for (statics/levels.ts#layoutExpansion). */
export const layoutKey = (face: number, index: number, suffix: string): string => `x:${face}:${index}:${suffix}`;

/** CR 305.6: basic land types and the mana they imply. */
export const BASIC_LAND_MANA: Record<string, Color> = { Plains: 'W', Island: 'U', Swamp: 'B', Mountain: 'R', Forest: 'G' };

/** The intrinsic mana ability of a basic land type (CR 305.6). */
export function basicLandAbility(color: Color): ActivatedAbilityDef {
  return {
    kind: 'activated',
    text: `{T}: Add {${color}}.`,
    cost: { tap: true },
    isMana: true,
    effect: { targets: [], steps: [{ op: 'addMana', who: { ref: 'you' }, units: [[color]] }] },
  };
}

/**
 * What a keyword instance stands for (CR 702): the library's expansion, or nothing for a keyword the registry does not know or that has no expansion (a flag
 * or hook keyword is its own ability: the engine reads `c.keywords`). Pure.
 */
export function expansionOf(kw: KeywordAbilityDef, ctx: ExpandContext): AbilityDef[] {
  return keywordRegistry.get(kw.keyword) === undefined ? [] : keywordRegistry.expand(kw, ctx);
}

/**
 * The abilities of a base record as `CharAbility`s: printed ones first, then what the keyword library generates from the printed keywords, then (M6-6) what
 * the printed Class levels, leveler brackets and Cases stand for (origin 'keyword': generated from printed text, removed with it, carried inline on the stack).
 */
export function charAbilitiesOfBase(base: BaseChars): CharAbility[] {
  const out: CharAbility[] = base.abilities.map((a) => ({ key: printedKey(a.face, a.index), origin: 'printed', face: a.face, index: a.index, def: a.def }));
  return [...out, ...printedKeywordExpansions(out, base), ...layoutExpansions(out)];
}

/** M6-6 (m6 design 3.7): the abilities the layout structures among `printed` stand for, keyed `x:<face>:<index>:<n>` (statics/levels.ts). Pure. */
export function layoutExpansions(printed: readonly CharAbility[]): CharAbility[] {
  const out: CharAbility[] = [];
  for (const a of printed) {
    for (const p of layoutExpansion(a.def)) out.push({ key: layoutKey(a.face, a.index, p.suffix), origin: 'keyword', face: a.face, index: a.index, def: p.def, parent: a.key });
  }
  return out;
}

/**
 * What the keyword library generates from the PRINTED keyword abilities among `printed` (origin 'printed'), keyed `k:<face>:<index>:<n>`. Each instance is
 * expanded with its ordinal among the printed instances of its family on its face (M6-5a, CR 702.33b, 702.33f, 607.2i: the two kicker costs of "Kicker {A}
 * and/or {B}" are "kicker" and "kicker:2"; a multikicker cost is a kicker cost, CR 702.33c). Pure. actions/cast-options.ts reads it over `faceChars`, which
 * holds printed abilities only, so a card's keyword costs (kicker, buyback, entwine, evoke) are offered as it is cast (CR 601.2b).
 */
export function printedKeywordExpansions(printed: readonly CharAbility[], c: Pick<BaseChars, 'names' | 'name' | 'types'>): CharAbility[] {
  const out: CharAbility[] = [];
  const seen = new Map<string, number>();
  for (const a of printed) {
    if (a.origin !== 'printed' || a.def.kind !== 'keyword') continue;
    const data = keywordRegistry.get(a.def.keyword);
    if (data === undefined) continue; // (most keywords are flags: nothing to expand)
    const family = `${a.face}|${data.family ?? data.name}`;
    const ordinal = (seen.get(family) ?? 0) + 1;
    seen.set(family, ordinal);
    const parent = printedKey(a.face, a.index);
    const ctx: ExpandContext = { granted: false, faceName: c.names[a.face] ?? c.name, types: c.types, keyPrefix: `k:${a.face}:${a.index}`, ...(ordinal > 1 ? { ordinal } : {}) };
    expansionOf(a.def, ctx).forEach((def, n) => out.push({ key: keywordKey(a.face, a.index, n), origin: 'keyword', face: a.face, index: a.index, def, parent }));
  }
  return out;
}

// ---- copied abilities (M6-2, m6 design E5, E20; CR 707.2, 707.7) ------------------------------------------------------------------------------------

/** M6-2 (E5): the key of a copied printed ability, `c:<effectId>:<face>:<index>`. */
export const copiedKey = (effectId: string, face: number, index: number): string => `c:${effectId}:${face}:${index}`;

/**
 * M6-2 (E20, CR 707.7): the link ids of a copied ability, moved into the namespace `ns` (statics/links.ts#grantNamespace's form, `<ns>#<link>`): every `link`
 * field and every string `chosen` field (a layer 4 / layer 5 "the chosen ..." value). Pure; memoized per (definition, namespace). `ns === null` keeps the bare
 * ids (a copy effect that began as its object entered: the object's link store is new, CR 400.7, so bare ids are already the copy effect's own).
 */
export function namespacedAbility(def: AbilityDef, ns: string | null): AbilityDef {
  if (ns === null) return def;
  // a memo of a pure function of immutable data (like statics/layers.ts#templateFor): only for a frozen definition; an unfrozen one is rewritten every time
  if (!Object.isFrozen(def)) return rewriteLinks(def, ns) as AbilityDef;
  let byNs = NAMESPACED.get(def);
  if (!byNs) NAMESPACED.set(def, (byNs = new Map()));
  let out = byNs.get(ns);
  if (!out) byNs.set(ns, (out = deepFreeze(rewriteLinks(def, ns)) as AbilityDef));
  return out;
}

function deepFreeze<T>(v: T): T {
  if (v !== null && typeof v === 'object' && !Object.isFrozen(v)) {
    for (const x of Object.values(v as object)) deepFreeze(x);
    Object.freeze(v);
  }
  return v;
}
const NAMESPACED = new WeakMap<AbilityDef, Map<string, AbilityDef>>();

function rewriteLinks(v: unknown, ns: string): unknown {
  if (Array.isArray(v)) return v.map((x) => rewriteLinks(x, ns));
  if (v === null || typeof v !== 'object') return v;
  const out: Record<string, unknown> = {};
  for (const [k, x] of Object.entries(v as Record<string, unknown>)) {
    // MX2 (additive): a keyword quality read from a linked choice (`quality: 'chosen:<link>'`, statics/mods.ts#withChosenQualities) moves with its link
    if (k === 'quality' && typeof x === 'string' && x.startsWith('chosen:')) out[k] = `chosen:${ns}#${x.slice('chosen:'.length)}`;
    else out[k] = (k === 'link' || k === 'chosen') && typeof x === 'string' ? `${ns}#${x}` : rewriteLinks(x, ns);
  }
  return out;
}

/**
 * M6-2 (E5): the abilities a copy effect gives (CR 707.2: the copied rules text): each printed ability of the copied face keyed `c:<effectId>:<face>:<index>`,
 * then what the keyword library generates from the copied keywords keyed `c:<effectId>:<face>:<index>:<n>`, all with origin `copied`. `extra` are abilities that
 * are part of the copiable values without being printed on the copied face (an "except it has ..." exception, CR 707.9b; a merged component's abilities,
 * CR 702.140e): keyed `c:<effectId>:x:<n>`. Links are namespaced with `ns` (see `namespacedAbility`). Pure.
 */
export function copiedAbilities(effectId: string, base: BaseChars, extra: readonly AbilityDef[], ns: string | null): CharAbility[] {
  const out: CharAbility[] = base.abilities.map((a) => ({ key: copiedKey(effectId, a.face, a.index), origin: 'copied', face: a.face, index: a.index, def: namespacedAbility(a.def, ns) }));
  extra.forEach((def, n) => out.push({ key: `c:${effectId}:x:${n}`, origin: 'copied', face: base.face, index: -1, def: namespacedAbility(def, ns) }));
  const seen = new Map<string, number>();
  for (const a of [...out]) {
    if (a.def.kind !== 'keyword') continue;
    const data = keywordRegistry.get(a.def.keyword);
    if (data === undefined) continue; // (most keywords are flags: nothing to expand)
    const family = `${a.face}|${data.family ?? data.name}`;
    const ordinal = (seen.get(family) ?? 0) + 1;
    seen.set(family, ordinal);
    const ctx: ExpandContext = { granted: false, faceName: base.names[a.face] ?? base.name, types: base.types, keyPrefix: a.key, ...(ordinal > 1 ? { ordinal } : {}) };
    expansionOf(a.def, ctx).forEach((def, n) => out.push({ key: `${a.key}:${n}`, origin: 'copied', face: a.face, index: a.index, def: namespacedAbility(def, ns), parent: a.key }));
  }
  // M6-6 (CR 707.2, 716.2b, 711.2, 719.3b): a copy has the copied Class levels, leveler brackets and Cases; the level and solved designations are not copied
  for (const a of [...out]) {
    for (const p of layoutExpansion(a.def)) out.push({ key: `${a.key}:x:${p.suffix}`, origin: 'copied', face: a.face, index: a.index, def: p.def, parent: a.key });
  }
  return out;
}

/** Printed abilities only (what a definition has before any object exists: `faceChars`, `combinedChars`). */
export const printedCharAbilities = (base: BaseChars): CharAbility[] =>
  base.abilities.map((a) => ({ key: printedKey(a.face, a.index), origin: 'printed', face: a.face, index: a.index, def: a.def }));

/** M6-6: can `ruleAbilitiesFor` give this object anything (a land, CR 305.6; a Saga, CR 714.3a-b)? A cheap test for the callers that skip it otherwise. */
export const mayHaveRuleAbilities = (c: Pick<Chars, 'types' | 'subtypes'>): boolean => (c.types as string[]).includes('Land') || c.subtypes.includes('Saga');

/**
 * CR 305.6: an object with the land type and a basic land type has the intrinsic ability. The abilities to add to `c`, in basic-type order, none it already has.
 * M6-6: and a Saga has its intrinsic "enters with lore counters" abilities (CR 714.3a-b, statics/levels.ts#sagaRuleAbilities).
 */
export function ruleAbilitiesFor(c: Pick<Chars, 'types' | 'subtypes' | 'face' | 'abilities'>): CharAbility[] {
  if (!(c.types as string[]).includes('Land')) return sagaRuleAbilities(c);
  const out: CharAbility[] = [];
  for (const t of BASIC_LAND_TYPES) {
    if (!c.subtypes.includes(t)) continue;
    const color = BASIC_LAND_MANA[t]!;
    const key = basicKey(color);
    if (c.abilities.some((a) => a.key === key)) continue;
    out.push({ key, origin: 'rule', face: c.face, index: -1, def: basicLandAbility(color) });
  }
  return c.subtypes.includes('Saga') ? [...out, ...sagaRuleAbilities(c)] : out; // a Saga land (Urza's Saga)
}

/**
 * Abilities a layer 6 effect gives an object: one `g:` ability per granted definition, plus what a granted keyword expands into (CR 613.1f: granted keywords are
 * expanded on the fly). `blocked` are the names the object "can't have" (layer 6): such a keyword is not granted.
 */
export function grantedAbilities(effectId: string, timestamp: number, defs: readonly AbilityDef[], c: Pick<Chars, 'face' | 'names' | 'name' | 'types'> & { manaCost?: Chars['manaCost'] }, blocked: readonly string[]): CharAbility[] {
  const out: CharAbility[] = [];
  defs.forEach((def, n) => {
    if (def.kind === 'keyword' && blocked.includes(def.keyword)) return;
    const key = grantedKey(effectId, n);
    out.push({ key, origin: 'granted', face: c.face, index: -1, def, grantedBy: effectId, grantedAt: timestamp });
    if (def.kind !== 'keyword') return;
    // r5-cost: for costIsManaCost; trek-7: except where the cost is that of the face cast (keywords/expand.ts#MANA_COST_OF_FACE_CAST: nothing is expanded here, castOptionsOf does it)
    const ofFace = def.costIsManaCost === true && def.cost === undefined && MANA_COST_OF_FACE_CAST.has(def.keyword);
    const ctx: ExpandContext = { granted: true, faceName: c.names[c.face] ?? c.name, types: c.types, keyPrefix: key, ...(c.manaCost !== undefined && !ofFace ? { manaCost: c.manaCost } : {}) };
    expansionOf(def, ctx).forEach((x, j) => out.push({ key: `${key}:${j}`, origin: 'granted', face: c.face, index: -1, def: x, grantedBy: effectId, grantedAt: timestamp, parent: key }));
  });
  return out;
}

/** The keyword abilities among a list of abilities, in order (CR 702): what `Chars.keywords` is. */
export const keywordsOfAbilities = (abilities: readonly CharAbility[]): KeywordAbilityDef[] => abilities.flatMap((a) => (a.def.kind === 'keyword' ? [a.def] : []));
